#include <stdio.h>
#include <stdbool.h>

#define CAP 5

typedef struct {
    int buf[CAP];
    int head;   /* index of oldest element */
    int tail;   /* index where next element will be written */
    int size;   /* disambiguates head == tail: 0 means empty, CAP means full */
} RingQueue;

void rq_init(RingQueue *q) { q->head = q->tail = q->size = 0; }

bool rq_enqueue(RingQueue *q, int x) {
    if (q->size == CAP) return false;
    q->buf[q->tail] = x;
    q->tail = (q->tail + 1) % CAP;
    q->size++;
    return true;
}

bool rq_dequeue(RingQueue *q, int *out) {
    if (q->size == 0) return false;
    *out = q->buf[q->head];
    q->head = (q->head + 1) % CAP;
    q->size--;
    return true;
}

int main(void) {
    RingQueue q;
    rq_init(&q);
    for (int i = 1; i <= 5; i++) rq_enqueue(&q, i * 10);   /* fills the buffer, tail wraps to 0 */
    int v;
    rq_dequeue(&q, &v); printf("dequeued %d\n", v);
    rq_dequeue(&q, &v); printf("dequeued %d\n", v);
    rq_enqueue(&q, 60);                                     /* reuses the two freed slots */
    rq_enqueue(&q, 70);
    while (rq_dequeue(&q, &v)) printf("dequeued %d\n", v);
    return 0;
}
